import pdfplumber
import pandas as pd
import json

def parse_pdf(file_path):
    employees = {}
    with pdfplumber.open(file_path) as pdf:
        for page in pdf.pages:
            table = page.extract_table()
            if not table:
                continue
            headers = table[0]
            if headers[0] == 'ID':
                data_rows = table[1:]
            else:
                data_rows = table

            for row in data_rows:
                if not row or not row[0] or not row[0].startswith('EMP'):
                    continue
                emp_id = row[0]
                employees[emp_id] = {
                    'First': row[1],
                    'Last': row[2],
                    'Dept': row[3],
                    'Position': row[4],
                    'Salary': int(row[5].replace(',', '')),
                    'Years': int(row[6]),
                    'Location': row[7],
                    'Score': float(row[8])
                }
    return employees

def parse_excel(file_path):
    df = pd.read_excel(file_path)
    employees = {}
    for _, row in df.iterrows():
        emp_id = row['ID']
        employees[emp_id] = {
            'First': str(row['First']),
            'Last': str(row['Last']),
            'Dept': str(row['Dept']),
            'Position': str(row['Position']),
            'Salary': int(row['Salary']),
            'Years': int(row['Years']),
            'Location': str(row['Location']),
            'Score': float(row['Score'])
        }
    return employees

pdf_data = parse_pdf('employees_backup.pdf')
excel_data = parse_excel('employees_current.xlsx')

deleted_employees = []
for emp_id in pdf_data:
    if emp_id not in excel_data:
        deleted_employees.append(emp_id)

modified_employees = []
for emp_id, old_record in pdf_data.items():
    if emp_id in excel_data:
        new_record = excel_data[emp_id]
        for field in old_record:
            if old_record[field] != new_record[field]:
                modified_employees.append({
                    'id': emp_id,
                    'field': field,
                    'old_value': old_record[field],
                    'new_value': new_record[field]
                })

deleted_employees.sort()
modified_employees.sort(key=lambda x: (x['id'], x['field']))

report = {
    'deleted_employees': deleted_employees,
    'modified_employees': modified_employees
}

with open('diff_report.json', 'w') as f:
    json.dump(report, f, indent=2)

print("Report generated successfully.")

